	FOREIGN KEY (`_parent_id`) REFERENCES `checklist`(`id`) ON UPDATE no action ON DELETE cascade
);
CREATE TABLE `_checklist_v_version_items` (
	`_order` integer NOT NULL,
	`_parent_id` integer NOT NULL,
	`id` integer PRIMARY KEY NOT NULL,
	`number` text,
	`heading` text,
	`description` text,
	`locked` integer DEFAULT false,
	`_uuid` text,
	FOREIGN KEY (`_parent_id`) REFERENCES `_checklist_v`(`id`) ON UPDATE no action ON DELETE cascade
);
INSERT INTO "media" ("id", "alt", "updated_at", "created_at", "url", "thumbnail_u_r_l", "filename", "mime_type", "filesize", "width", "height") VALUES (1, 'Infographic from Canopy Embedded Labs titled “How to Choose the Right IoT Protocol.” It lists five questions to ask (range, data, power source, environment, monthly cost) and compares six options: Bluetooth Low Energy, Wi-Fi, LoRa, Wi-SUN, cellular NB-IoT/4G and wired RS485/Modbus.', '2026-10-26T20:11:02.579Z', '2026-10-26T20:11:02.577Z', '/api/media/file/Choosing%20the%20Right%20IoT%20Protocol.png', NULL, 'Choosing the Right IoT Protocol.png', 'image/png', 1801491, 1254, 1254);
