INSERT INTO "testimonial" ("id", "heading", "client_label", "quote", "order", "updated_at", "created_at") VALUES (1, 'From idea toward a real product', 'Canopy client', 'Bringing design, electronics, and software into the same conversation helped us make more confident decisions.', 3, '2026-10-26T20:14:04.387Z', '2026-10-26T20:11:56.992Z');
INSERT INTO "testimonial" ("id", "heading", "client_label", "quote", "order", "updated_at", "created_at") VALUES (2, 'A thoughtful engineering partner', 'Canopy client', 'We appreciate the care taken to understand the problem, share options, and keep the project moving as one team.', 2, '2026-10-26T20:14:04.538Z', '2026-10-26T20:11:57.095Z');
INSERT INTO "testimonial" ("id", "heading", "client_label", "quote", "order", "updated_at", "created_at") VALUES (3, 'A collaborative product team', 'Canopy client', 'The value of an integrated team is being able to work through product decisions together, early, and with the full context in view.', 1, '2026-10-26T20:14:04.680Z', '2026-10-26T20:11:57.215Z');
INSERT INTO "page" ("id", "title", "heading", "subheading", "url", "body", "company_facts_name", "company_facts_location", "company_facts_contact_email", "seo_seo_title", "seo_meta_description", "seo_canonical_url", "seo_robots_index", "seo_robots_follow", "seo_schema_type", "updated_at", "created_at", "_status", "eyebrow", "page_type", "seo_keywords", "seo_og_title", "seo_og_description", "seo_og_image_id", "hero_image_id", "cta_label", "cta_href") VALUES (1, 'About', 'About Canopy Embedded Labs', 'A full-stack product realization lab in Chennai, India. Ideate. Innovate. Launch.', '/about/', NULL, NULL, NULL, NULL, 'About Canopy Embedded Labs | Chennai, India', 'Canopy Embedded Labs is a full-stack electronics product development team in Chennai, India, with 25+ years of R&D experience.', '', 1, 1, 'auto', '2026-10-26T20:13:52.643Z', '2026-10-26T20:11:52.625Z', 'draft', '', 'landing left', '', '', '', NULL, 5, '', '');
INSERT INTO "page" ("id", "title", "heading", "subheading", "url", "body", "company_facts_name", "company_facts_location", "company_facts_contact_email", "seo_seo_title", "seo_meta_description", "seo_canonical_url", "seo_robots_index", "seo_robots_follow", "seo_schema_type", "updated_at", "created_at", "_status", "eyebrow", "page_type", "seo_keywords", "seo_og_title", "seo_og_description", "seo_og_image_id", "hero_image_id", "cta_label", "cta_href") VALUES (2, 'Engagement Model', 'See the process. Talk to an engineer to start.', 'Whether you''re starting from an idea or already mid-build, the Productized R&D Subscription puts hardware, firmware, mechanical, and cloud under one roof. Six steps, start to kickoff. Send the form and an engineer follows up — no need to wait for a call slot to open up.', '/engagement-model/', '{"root":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"We don''t hand off a spec sheet and disappear. One team stays hands-on from first schematic to field-ready product — no vendor handoffs in between.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1}],"direction":null,"format":"","indent":0,"version":1}}', NULL, NULL, NULL, 'Productized R&D Subscription | Canopy Embedded Labs', 'One contract for hardware, firmware, mechanical and cloud. Six steps from scoping call to kickoff, with fixed-milestone pricing.', '', 1, 1, 'FAQPage', '2026-10-26T20:13:53.282Z', '2026-10-26T20:11:52.999Z', 'draft', 'Productized R&D Subscription', 'landing', '', '', '', NULL, NULL, '', '');
INSERT INTO "page" ("id", "title", "heading", "subheading", "url", "body", "company_facts_name", "company_facts_location", "company_facts_contact_email", "seo_seo_title", "seo_meta_description", "seo_canonical_url", "seo_robots_index", "seo_robots_follow", "seo_schema_type", "updated_at", "created_at", "_status", "eyebrow", "page_type", "seo_keywords", "seo_og_title", "seo_og_description", "seo_og_image_id", "hero_image_id", "cta_label", "cta_href") VALUES (3, 'Insights', 'Engineering Notes From Inside the Build.', 'The same technical breakdowns we post to LinkedIn — recalls, memory architecture, signal integrity, OTA pipelines — published here in full, so they''re searchable and citable long after the post scrolls out of a feed.', '/insights/', NULL, NULL, NULL, NULL, 'Embedded Engineering Insights | Canopy Embedded Labs', 'Engineering insights on firmware, PCB design, BMS, OTA and IoT, written for founders and CTOs making hardware product decisions.', '', 1, 1, 'auto', '2026-10-26T20:13:53.916Z', '2026-10-26T20:11:53.245Z', 'draft', 'Embedded Engineering Insights', 'landing', '', '', '', NULL, NULL, 'Browse Articles', '#latest-articles');
INSERT INTO "page" ("id", "title", "heading", "subheading", "url", "body", "company_facts_name", "company_facts_location", "company_facts_contact_email", "seo_seo_title", "seo_meta_description", "seo_canonical_url", "seo_robots_index", "seo_robots_follow", "seo_schema_type", "updated_at", "created_at", "_status", "eyebrow", "page_type", "seo_keywords", "seo_og_title", "seo_og_description", "seo_og_image_id", "hero_image_id", "cta_label", "cta_href") VALUES (4, 'Portfolio', 'Ideas We''ve Turned Into Working Products.', 'Every product here started as somebody else''s idea and a gap in execution capability — no in-house hardware, firmware, or mechanical team to close it. We closed it. Pick a product from the index below to see the full build story, in place — no page reload.', '/work/', NULL, NULL, NULL, NULL, 'BMS, Charger & IoT Projects | Canopy Embedded Labs', 'Electronics product development portfolio: a smart BMS, a dual-channel Li-ion charger and a BLE Mesh + RS485 energy meter node.', '', 1, 1, 'auto', '2026-10-26T20:13:54.449Z', '2026-10-26T20:11:53.529Z', 'draft', 'Electronics Product Development Portfolio', 'landing left', '', '', '', NULL, NULL, '', '');
INSERT INTO "page" ("id", "title", "heading", "subheading", "url", "body", "company_facts_name", "company_facts_location", "company_facts_contact_email", "seo_seo_title", "seo_meta_description", "seo_canonical_url", "seo_robots_index", "seo_robots_follow", "seo_schema_type", "updated_at", "created_at", "_status", "eyebrow", "page_type", "seo_keywords", "seo_og_title", "seo_og_description", "seo_og_image_id", "hero_image_id", "cta_label", "cta_href") VALUES (5, 'Home', 'Electronics Product Development — One Team, Schematic to Cloud.', 'If it runs on electronics, We can build it for you!', '/', '{"root":{"type":"root","children":[{"type":"paragraph","children":[],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1}],"direction":null,"format":"","indent":0,"version":1}}', NULL, NULL, NULL, 'Canopy Embedded Labs | Electronics Product Development, India', 'Your trusted partner for electronics product development: PCB design, firmware, enclosures, UI/UX and IoT cloud apps from one team. No vendor handoffs.', '', 1, 1, 'Organization', '2026-10-26T20:13:55.164Z', '2026-10-26T20:11:53.848Z', 'draft', '', 'landing', '', '', '', NULL, NULL, '', '');
