INSERT INTO "section" ("id", "title", "heading", "subheading", "image_id", "body", "updated_at", "created_at", "eyebrow", "tag_line", "highlight", "type", "image_alt", "background_image", "background_video", "cta_label", "cta_href", "summary", "preview_alt", "section_key", "heading_first_line", "heading_second_line", "logo", "image_url", "mockup_assistant_name", "mockup_scheduling_message", "mockup_sync_title", "mockup_telemetry_title", "secondary_cta_label", "secondary_cta_href", "controls_tabs_label", "controls_previous_label", "controls_next_label", "variant", "columns", "anchor", "tags", "hidden") VALUES (100, 'About - Who', 'Who We Are', 'Led by a Principal Solution Architect with 13+ years of R&D experience, the team brings 25+ years of R&D experience across BMS/EV, industrial IoT, healthcare devices, automotive and energy metering.', NULL, NULL, '2026-10-26T20:13:44.465Z', '2026-10-26T20:11:49.072Z', '02', NULL, NULL, 'team', NULL, NULL, NULL, '', '', NULL, NULL, 'who', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, NULL, '', NULL, '', '', 0);
INSERT INTO "section" ("id", "title", "heading", "subheading", "image_id", "body", "updated_at", "created_at", "eyebrow", "tag_line", "highlight", "type", "image_alt", "background_image", "background_video", "cta_label", "cta_href", "summary", "preview_alt", "section_key", "heading_first_line", "heading_second_line", "logo", "image_url", "mockup_assistant_name", "mockup_scheduling_message", "mockup_sync_title", "mockup_telemetry_title", "secondary_cta_label", "secondary_cta_href", "controls_tabs_label", "controls_previous_label", "controls_next_label", "variant", "columns", "anchor", "tags", "hidden") VALUES (101, 'About - Why', 'Why We Exist', '', NULL, '{"root":{"type":"root","children":[{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Most hardware products are built by five vendors: one for the PCB, one for firmware, one for the enclosure, one for industrial design, one for the app. Nobody owns the gaps between them, so the founder or CTO ends up managing vendors instead of the product. Canopy Embedded Labs was set up to remove those gaps — every discipline in one team, under one contract.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1}],"direction":null,"format":"","indent":0,"version":1}}', '2026-10-26T20:13:44.841Z', '2026-10-26T20:11:49.204Z', '01', NULL, NULL, 'text', NULL, NULL, NULL, '', '', NULL, NULL, 'why', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '', '', NULL, NULL, NULL, 'lead', NULL, '', '', 0);
