INSERT INTO "card" ("id", "title", "heading", "subheading", "category", "image_id", "description", "additional_description", "cta_label", "cta_url", "type", "updated_at", "created_at", "image_url", "index", "value", "role", "date", "image_alt", "icon", "theme", "short_description", "body", "read_more_label", "linkedin_url", "tags") VALUES (231, 'yrs R&D experience', NULL, '', NULL, NULL, NULL, NULL, '', '', 'stat', '2026-10-26T20:12:47.706Z', '2026-10-26T20:11:35.914Z', NULL, NULL, '25+', NULL, NULL, NULL, '', NULL, '', NULL, NULL, NULL, '');
INSERT INTO "card" ("id", "title", "heading", "subheading", "category", "image_id", "description", "additional_description", "cta_label", "cta_url", "type", "updated_at", "created_at", "image_url", "index", "value", "role", "date", "image_alt", "icon", "theme", "short_description", "body", "read_more_label", "linkedin_url", "tags") VALUES (232, 'Do we get the source code and design files?', NULL, '', NULL, NULL, NULL, NULL, '', '', NULL, '2026-10-26T20:12:47.892Z', '2026-10-26T20:11:35.960Z', NULL, NULL, '', NULL, NULL, NULL, '', NULL, 'Yes, in editable formats, not just a finished board: schematic and layout files, firmware source, mechanical CAD and app code. Any team can pick the product up later, so you are never locked in to us.', NULL, NULL, NULL, '');
INSERT INTO "card" ("id", "title", "heading", "subheading", "category", "image_id", "description", "additional_description", "cta_label", "cta_url", "type", "updated_at", "created_at", "image_url", "index", "value", "role", "date", "image_alt", "icon", "theme", "short_description", "body", "read_more_label", "linkedin_url", "tags") VALUES (233, 'Will you sign an NDA before we share our idea?', NULL, '', NULL, NULL, NULL, NULL, '', '', NULL, '2026-10-26T20:12:48.016Z', '2026-10-26T20:11:36.015Z', NULL, NULL, '', NULL, NULL, NULL, '', NULL, 'Yes. Tell us before the scoping call and we sign an NDA first, so you can describe the full idea without holding anything back.', NULL, NULL, NULL, '');
INSERT INTO "card" ("id", "title", "heading", "subheading", "category", "image_id", "description", "additional_description", "cta_label", "cta_url", "type", "updated_at", "created_at", "image_url", "index", "value", "role", "date", "image_alt", "icon", "theme", "short_description", "body", "read_more_label", "linkedin_url", "tags") VALUES (234, 'Who owns the intellectual property?', NULL, '', NULL, NULL, NULL, NULL, '', '', NULL, '2026-10-26T20:12:48.160Z', '2026-10-26T20:11:36.068Z', NULL, NULL, '', NULL, NULL, NULL, '', NULL, 'You do. The schematics, PCB layout, firmware source, mechanical CAD, app code and documentation we produce for you belong to you under the contract.', NULL, NULL, NULL, '');
INSERT INTO "card" ("id", "title", "heading", "subheading", "category", "image_id", "description", "additional_description", "cta_label", "cta_url", "type", "updated_at", "created_at", "image_url", "index", "value", "role", "date", "image_alt", "icon", "theme", "short_description", "body", "read_more_label", "linkedin_url", "tags") VALUES (235, 'How is pricing structured?', NULL, '', NULL, NULL, NULL, NULL, '', '', NULL, '2026-10-26T20:12:48.288Z', '2026-10-26T20:11:36.113Z', NULL, NULL, '', NULL, NULL, NULL, '', NULL, 'Every engagement is scoped and priced against fixed milestones after the scoping call and your PRD — a real number for real deliverables, not an hourly rate card.', NULL, NULL, NULL, '');
INSERT INTO "card" ("id", "title", "heading", "subheading", "category", "image_id", "description", "additional_description", "cta_label", "cta_url", "type", "updated_at", "created_at", "image_url", "index", "value", "role", "date", "image_alt", "icon", "theme", "short_description", "body", "read_more_label", "linkedin_url", "tags") VALUES (236, 'What if we already have some capability in-house?', NULL, '', NULL, NULL, NULL, NULL, '', '', NULL, '2026-10-26T20:12:48.448Z', '2026-10-26T20:11:36.160Z', NULL, NULL, '', NULL, NULL, NULL, '', NULL, 'We slot in around what you already have and own the disciplines you don''t — the engagement scope is defined at the scoping call, not fixed in advance.', NULL, NULL, NULL, '');
INSERT INTO "card" ("id", "title", "heading", "subheading", "category", "image_id", "description", "additional_description", "cta_label", "cta_url", "type", "updated_at", "created_at", "image_url", "index", "value", "role", "date", "image_alt", "icon", "theme", "short_description", "body", "read_more_label", "linkedin_url", "tags") VALUES (237, 'How is this different from hiring an agency?', NULL, '', NULL, NULL, NULL, NULL, '', '', NULL, '2026-10-26T20:12:48.745Z', '2026-10-26T20:11:36.208Z', NULL, NULL, '', NULL, NULL, NULL, '', NULL, 'An agency subcontracts what it can''t do in-house — you inherit their vendor handoffs. We run every discipline as one internal team, so there''s no seam to hide a bug in.', NULL, NULL, NULL, '');
