INSERT INTO "card" ("id", "title", "heading", "subheading", "category", "image_id", "description", "additional_description", "cta_label", "cta_url", "type", "updated_at", "created_at", "image_url", "index", "value", "role", "date", "image_alt", "icon", "theme", "short_description", "body", "read_more_label", "linkedin_url", "tags") VALUES (249, 'Accept & Send PO', NULL, 'One contract. One signature.', NULL, NULL, NULL, NULL, '', '', NULL, '2026-10-26T20:12:50.917Z', '2026-10-26T20:11:36.883Z', NULL, NULL, '', NULL, NULL, NULL, '', NULL, 'Accept the proposal and issue a PO — no separate contracts per discipline, no vendor-by-vendor negotiation.', NULL, NULL, NULL, '');
INSERT INTO "card" ("id", "title", "heading", "subheading", "category", "image_id", "description", "additional_description", "cta_label", "cta_url", "type", "updated_at", "created_at", "image_url", "index", "value", "role", "date", "image_alt", "icon", "theme", "short_description", "body", "read_more_label", "linkedin_url", "tags") VALUES (250, 'Get a Proposal', NULL, 'Fixed milestones, priced against your actual spec.', NULL, NULL, NULL, NULL, '', '', NULL, '2026-10-26T20:12:51.081Z', '2026-10-26T20:11:36.926Z', NULL, NULL, '', NULL, NULL, NULL, '', NULL, 'A scoped proposal comes back — real deliverables and a real number, not an open-ended hourly estimate.', NULL, NULL, NULL, '');
INSERT INTO "card" ("id", "title", "heading", "subheading", "category", "image_id", "description", "additional_description", "cta_label", "cta_url", "type", "updated_at", "created_at", "image_url", "index", "value", "role", "date", "image_alt", "icon", "theme", "short_description", "body", "read_more_label", "linkedin_url", "tags") VALUES (251, 'Submit the PRD', NULL, 'Bring us what you have — we scope against it, not a guess.', NULL, NULL, NULL, NULL, '', '', NULL, '2026-10-26T20:12:51.407Z', '2026-10-26T20:11:36.995Z', NULL, NULL, '', NULL, NULL, NULL, '', NULL, 'Share your product requirements doc, even a rough one. It''s what the proposal gets priced and milestoned against.', NULL, NULL, NULL, '');
