INSERT INTO "case_study" ("id", "title", "slug", "heading", "subheading", "category", "body", "tags", "images_landing_image_id", "card_cta_label", "card_cta_link", "page_cta_label", "page_cta_link", "project_stage", "seo_seo_title", "seo_meta_description", "seo_canonical_url", "seo_robots_index", "seo_robots_follow", "seo_schema_type", "updated_at", "created_at", "_status", "seo_keywords", "seo_og_title", "seo_og_description", "seo_og_image_id", "featured") VALUES (1, 'Smart Dual-Channel Li-ion Charger', 'dual-channel-charger', 'Smart Dual-Channel Li-ion Charger: Two Channels, One Team', 'A high-efficiency dual-pack charging platform where power stage electronics and control firmware are co-designed from day one.', 'Power Electronics & Firmware', '{"root":{"type":"root","children":[{"type":"heading","tag":"h2","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Platform Features & Capabilities","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"The charger automatically detects and negotiates charging requirements for each attached battery independently, operating safely across demanding temperature ranges. It features fail-safe default charging profiles, per-output status lighting, comprehensive hardware fault protection (including safe recovery of fully drained batteries), and a compact layout optimized for passive thermal airflow and minimal electrical noise.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","tag":"h2","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"The Engineering Gap We Closed","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"heading","tag":"h3","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Power Electronics & Two-Channel Architecture","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Engineered independent dual power stages sharing a unified thermal dissipation path and optimized PCB layout budget to eliminate cross-channel interference.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","tag":"h3","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Charge-Control Firmware","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Developed closed-loop charge profile logic written specifically against the physical hardware characteristics rather than relying on generic reference schematics.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","tag":"h3","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Thermal & Enclosure Design","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Validated thermal dissipation performance using Computational Fluid Dynamics (CFD) simulation alongside DFM-optimized enclosure engineering.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1}],"direction":null,"format":"","indent":0,"version":1}}', 'Power Electronics, Battery Charger, Firmware, Thermal Design, CFD, Li-ion, Hardware Engineering, Smart BMS', 2, 'View Project', '/work/dual-channel-charger/', 'Talk to an Engineer', '#consultation', 'proto-built', 'Dual-Channel Smart Charger Design | Canopy Embedded Labs', 'Dual-channel Li-ion charger design with power electronics and control firmware engineered together.', '', 1, 1, 'auto', '2026-10-26T20:13:55.783Z', '2026-10-26T20:11:54.146Z', 'draft', '', '', '', NULL, 0);
INSERT INTO "case_study" ("id", "title", "slug", "heading", "subheading", "category", "body", "tags", "images_landing_image_id", "card_cta_label", "card_cta_link", "page_cta_label", "page_cta_link", "project_stage", "seo_seo_title", "seo_meta_description", "seo_canonical_url", "seo_robots_index", "seo_robots_follow", "seo_schema_type", "updated_at", "created_at", "_status", "seo_keywords", "seo_og_title", "seo_og_description", "seo_og_image_id", "featured") VALUES (2, 'Smart Battery Management System', 'smart-bms', 'Smart Battery Management System: From an Idea to a Field-Ready Design', 'A robust 4S Li-ion battery management system engineered with field-upgradable OTA capabilities, real-time telemetry, and continuous 20A power delivery.', 'Embedded Systems & Power Electronics', '{"root":{"type":"root","children":[{"type":"heading","tag":"h2","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Architectural Highlights & Features","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Designed for demanding deployment environments, the system features scalable pack sizes, live OLED/display telemetry showing real-time voltage, runtime, and battery percentage, alongside USB-C fast charging and dual auxiliary power outputs. Controlled via a single-button wake, reset, and display interface, it incorporates comprehensive hardware safety mechanisms and dedicated built-in programming ports.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","tag":"h2","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"The Engineering Gap We Closed","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"heading","tag":"h3","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Circuit & Pack Architecture","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Engineered advanced cell balancing topologies, integrated hardware protection circuitry, and optimized thermal stackups for pack-level layout integrity.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","tag":"h3","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Dual-Bank Bootloader (OTA-Ready)","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Implemented a resilient dual-bank bootloader architecture supporting cryptographically signed over-the-air (OTA) updates complete with automated fail-safe rollback execution.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","tag":"h3","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Hardware-in-the-Loop Validation","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Subjected the hardware and firmware to rigorous automated failure injection testing and boundary condition stress before live cells ever touched the prototype.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1}],"direction":null,"format":"","indent":0,"version":1}}', 'BMS, Battery Management, Power Electronics, Firmware, FreeRTOS, CAN Bus, OTA, Hardware Validation, ARM Cortex', 3, 'View Project', '/work/smart-bms/', 'Talk to an Engineer', '#consultation', 'in-design', 'Smart BMS with OTA-Ready Firmware | Canopy Embedded Labs', 'BMS design with fuel gauge, protection circuitry and OTA-ready firmware from one team.', '', 1, 1, 'auto', '2026-10-26T20:13:56.487Z', '2026-10-26T20:11:54.482Z', 'draft', '', '', '', NULL, 1);
INSERT INTO "checklist" ("id", "title", "slug", "locked_items_count", "pdf_asset_id", "form_id", "seo_seo_title", "seo_meta_description", "seo_canonical_url", "seo_robots_index", "seo_robots_follow", "seo_schema_type", "updated_at", "created_at", "_status", "access_gate_form_anchor", "seo_keywords", "seo_og_title", "seo_og_description", "seo_og_image_id", "heading", "subheading", "introduction", "items_heading") VALUES (1, 'The 10-Point UI/UX & Cloud Readiness Checklist', 'iot-app-cloud-readiness-checklist', 7, NULL, NULL, 'IoT App & Cloud Readiness Checklist | Canopy Embedded Labs', '10 gaps that cause BLE provisioning failures, fleet-scale cloud surprises and UX rewrites after launch. Check before you ship. Free PDF.', '', 1, 1, 'none', '2026-10-26T20:14:03.186Z', '2026-10-26T20:11:56.202Z', 'draft', NULL, '', '', '', NULL, 'The 10-Point UI/UX & Cloud Readiness Checklist', 'Run your product''s app, HMI, and cloud layer against the 10 gaps that cause provisioning failures, fleet-scale surprises, and post-launch UX rewrites — before you ship.', '', 'What the Checklist Covers');
INSERT INTO "checklist" ("id", "title", "slug", "locked_items_count", "pdf_asset_id", "form_id", "seo_seo_title", "seo_meta_description", "seo_canonical_url", "seo_robots_index", "seo_robots_follow", "seo_schema_type", "updated_at", "created_at", "_status", "access_gate_form_anchor", "seo_keywords", "seo_og_title", "seo_og_description", "seo_og_image_id", "heading", "subheading", "introduction", "items_heading") VALUES (2, 'The 10-Point Hardware Audit Checklist', 'hardware-audit-checklist', 7, NULL, NULL, 'Hardware Audit Checklist Before Mass Production | Canopy', 'The 10 failure points behind most field returns and recalls. Check your design before you tool for mass production. Free PDF.', '', 1, 1, 'none', '2026-10-26T20:14:03.786Z', '2026-10-26T20:11:56.571Z', 'draft', NULL, '', '', '', NULL, 'The 10-Point Hardware Audit Checklist', 'Run your design against the 10 failure points that cause the most field returns and recalls — the same checklist we use in scoping calls, before you tool for mass production.', '', 'What the Checklist Covers');
