INSERT INTO "capability" ("id", "title", "slug", "eyebrow", "heading", "subheading", "cta_label", "cta_href", "secondary_cta_label", "secondary_cta_href", "image_id", "image_alt", "included_heading", "why_heading", "why_text", "workflow_eyebrow", "workflow_heading", "workflow_intro", "workflow", "projects_heading", "insights_heading", "faq_heading", "seo_seo_title", "seo_meta_description", "seo_canonical_url", "seo_robots_index", "seo_robots_follow", "seo_keywords", "seo_og_title", "seo_og_description", "seo_og_image_id", "seo_schema_type", "updated_at", "created_at", "summary") VALUES (1, 'PCB Design', 'pcb-design', NULL, 'Hardware & PCB Design', 'PCBs engineered for signal integrity and manufacturability from the first placement pass — designed to get the board right in the first spin, not patched before a certification deadline.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'PCB Design & Layout Services, India | Canopy Embedded Labs', 'Multi-layer PCB design with SI/PI, RF, power electronics and DFM built in from the first placement pass, by the team that writes the firmware.', '', 1, 1, '', '', '', NULL, 'auto', '2026-10-26T20:13:57.752Z', '2026-10-26T20:11:55.197Z', 'PCBs engineered for signal integrity and manufacturability from the first placement pass — designed to get the board right in the first spin, not patched before a certification deadline.');
INSERT INTO "capability" ("id", "title", "slug", "eyebrow", "heading", "subheading", "cta_label", "cta_href", "secondary_cta_label", "secondary_cta_href", "image_id", "image_alt", "included_heading", "why_heading", "why_text", "workflow_eyebrow", "workflow_heading", "workflow_intro", "workflow", "projects_heading", "insights_heading", "faq_heading", "seo_seo_title", "seo_meta_description", "seo_canonical_url", "seo_robots_index", "seo_robots_follow", "seo_keywords", "seo_og_title", "seo_og_description", "seo_og_image_id", "seo_schema_type", "updated_at", "created_at", "summary") VALUES (2, 'Mechanical & Industrial Design', 'mechanical-industrial-design', NULL, 'Mechanical & Industrial Design', 'Form, function, and manufacturability decided together — from concept sketch to first-article inspection, not handed off between two separate teams.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'IP67 Enclosure & Industrial Design | Canopy Embedded Labs', 'DFM-ready enclosure CAD, thermal CFD, IP67/IP68 sealing, tolerance stack-up and CMF — form and manufacturability decided before tooling.', '', 1, 1, '', '', '', NULL, 'auto', '2026-10-26T20:13:58.174Z', '2026-10-26T20:11:55.326Z', 'Form, function, and manufacturability decided together — from concept sketch to first-article inspection, not handed off between two separate teams.');
