INSERT INTO "_case_study_v" ("id", "parent_id", "version_title", "version_slug", "version_heading", "version_subheading", "version_category", "version_body", "version_tags", "version_images_landing_image_id", "version_card_cta_label", "version_card_cta_link", "version_page_cta_label", "version_page_cta_link", "version_project_stage", "version_seo_seo_title", "version_seo_meta_description", "version_seo_canonical_url", "version_seo_robots_index", "version_seo_robots_follow", "version_seo_schema_type", "version_updated_at", "version_created_at", "version__status", "created_at", "updated_at", "latest", "tags", "version_seo_keywords", "version_seo_og_title", "version_seo_og_description", "version_seo_og_image_id", "version_featured") VALUES (1, 1, 'Smart Dual-Channel Li-ion Charger', 'dual-channel-charger', 'Smart Dual-Channel Li-ion Charger: Two Channels, One Team', 'A high-efficiency dual-pack charging platform where power stage electronics and control firmware are co-designed from day one.', 'Power Electronics & Firmware', '{"root":{"type":"root","children":[{"type":"heading","tag":"h2","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Platform Features & Capabilities","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"The charger automatically detects and negotiates charging requirements for each attached battery independently, operating safely across demanding temperature ranges. It features fail-safe default charging profiles, per-output status lighting, comprehensive hardware fault protection (including safe recovery of fully drained batteries), and a compact layout optimized for passive thermal airflow and minimal electrical noise.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","tag":"h2","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"The Engineering Gap We Closed","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"heading","tag":"h3","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Power Electronics & Two-Channel Architecture","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Engineered independent dual power stages sharing a unified thermal dissipation path and optimized PCB layout budget to eliminate cross-channel interference.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","tag":"h3","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Charge-Control Firmware","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Developed closed-loop charge profile logic written specifically against the physical hardware characteristics rather than relying on generic reference schematics.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","tag":"h3","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Thermal & Enclosure Design","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Validated thermal dissipation performance using Computational Fluid Dynamics (CFD) simulation alongside DFM-optimized enclosure engineering.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1}],"direction":null,"format":"","indent":0,"version":1}}', 'Power Electronics, Battery Charger, Firmware, Thermal Design, CFD, Li-ion, Hardware Engineering, Smart BMS', 2, 'View Project', '/work/dual-channel-charger/', 'Talk to an Engineer', '#consultation', 'proto-built', 'Dual-Channel Smart Charger Design | Canopy Embedded Labs', 'Dual-channel Li-ion charger design with power electronics and control firmware engineered together.', '', 1, 1, 'auto', '2026-10-26T20:11:54.147Z', '2026-10-26T20:11:54.146Z', 'draft', '2026-10-26T20:11:54.268Z', '2026-10-26T20:11:54.268Z', 0, NULL, '', '', '', NULL, 0);
INSERT INTO "_case_study_v" ("id", "parent_id", "version_title", "version_slug", "version_heading", "version_subheading", "version_category", "version_body", "version_tags", "version_images_landing_image_id", "version_card_cta_label", "version_card_cta_link", "version_page_cta_label", "version_page_cta_link", "version_project_stage", "version_seo_seo_title", "version_seo_meta_description", "version_seo_canonical_url", "version_seo_robots_index", "version_seo_robots_follow", "version_seo_schema_type", "version_updated_at", "version_created_at", "version__status", "created_at", "updated_at", "latest", "tags", "version_seo_keywords", "version_seo_og_title", "version_seo_og_description", "version_seo_og_image_id", "version_featured") VALUES (2, 2, 'Smart Battery Management System', 'smart-bms', 'Smart Battery Management System: From an Idea to a Field-Ready Design', 'A robust 4S Li-ion battery management system engineered with field-upgradable OTA capabilities, real-time telemetry, and continuous 20A power delivery.', 'Embedded Systems & Power Electronics', '{"root":{"type":"root","children":[{"type":"heading","tag":"h2","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Architectural Highlights & Features","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Designed for demanding deployment environments, the system features scalable pack sizes, live OLED/display telemetry showing real-time voltage, runtime, and battery percentage, alongside USB-C fast charging and dual auxiliary power outputs. Controlled via a single-button wake, reset, and display interface, it incorporates comprehensive hardware safety mechanisms and dedicated built-in programming ports.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","tag":"h2","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"The Engineering Gap We Closed","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"heading","tag":"h3","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Circuit & Pack Architecture","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Engineered advanced cell balancing topologies, integrated hardware protection circuitry, and optimized thermal stackups for pack-level layout integrity.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","tag":"h3","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Dual-Bank Bootloader (OTA-Ready)","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Implemented a resilient dual-bank bootloader architecture supporting cryptographically signed over-the-air (OTA) updates complete with automated fail-safe rollback execution.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","tag":"h3","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Hardware-in-the-Loop Validation","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Subjected the hardware and firmware to rigorous automated failure injection testing and boundary condition stress before live cells ever touched the prototype.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1}],"direction":null,"format":"","indent":0,"version":1}}', 'BMS, Battery Management, Power Electronics, Firmware, FreeRTOS, CAN Bus, OTA, Hardware Validation, ARM Cortex', 3, 'View Project', '/work/smart-bms/', 'Talk to an Engineer', '#consultation', 'in-design', 'Smart BMS with OTA-Ready Firmware | Canopy Embedded Labs', 'BMS design with fuel gauge, protection circuitry and OTA-ready firmware from one team.', '', 1, 1, 'auto', '2026-10-26T20:11:54.482Z', '2026-10-26T20:11:54.482Z', 'draft', '2026-10-26T20:11:54.579Z', '2026-10-26T20:11:54.579Z', 0, NULL, '', '', '', NULL, 1);
