INSERT INTO "_case_study_v" ("id", "parent_id", "version_title", "version_slug", "version_heading", "version_subheading", "version_category", "version_body", "version_tags", "version_images_landing_image_id", "version_card_cta_label", "version_card_cta_link", "version_page_cta_label", "version_page_cta_link", "version_project_stage", "version_seo_seo_title", "version_seo_meta_description", "version_seo_canonical_url", "version_seo_robots_index", "version_seo_robots_follow", "version_seo_schema_type", "version_updated_at", "version_created_at", "version__status", "created_at", "updated_at", "latest", "tags", "version_seo_keywords", "version_seo_og_title", "version_seo_og_description", "version_seo_og_image_id", "version_featured") VALUES (4, 2, 'Smart Battery Management System', 'smart-bms', 'Smart Battery Management System: From an Idea to a Field-Ready Design', 'A robust 4S Li-ion battery management system engineered with field-upgradable OTA capabilities, real-time telemetry, and continuous 20A power delivery.', 'Embedded Systems & Power Electronics', '{"root":{"type":"root","children":[{"type":"heading","tag":"h2","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Architectural Highlights & Features","version":1}],"direction":null,"format":"","indent":0,"version":1},{"type":"paragraph","children":[{"type":"text","detail":0,"format":0,"mode":"normal","style":"","text":"Designed for demanding deployment environments, the system features scalable pack sizes, live OLED/display telemetry showing real-time voltage, runtime, and battery percentage, alongside USB-C fast charging and dual auxiliary power outputs. Controlled via a single-button wake, reset, and display interface, it incorporates comprehensive hardware safety mechanisms and dedicated built-in programming ports.","version":1}],"direction":null,"format":"","indent":0,"textFormat":0,"textStyle":"","version":1},{"type":"heading","tag":"h2","children":[{"type":"text","detail":0,"