ersion":1},{"detail":0,"format":0,"mode":"normal","style":"","text":" Inside a smart home, deep in a metal-walled factory, or in a field with no Wi-Fi. Walls, metal and electrical noise all change what works.","type":"text","version":1}],"direction":null,"format":"","indent":0,"type":"listitem","version":1,"value":4},{"children":[{"detail":0,"format":1,"mode":"normal","style":"","text":"What will it cost per device, every month?","type":"text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":" Some options need a SIM card and a data plan for every unit. At 10,000 devices, that adds up fast.","type":"text","version":1}],"direction":null,"format":"","indent":0,"type":"listitem","version":1,"value":5}],"direction":null,"format":"","indent":0,"type":"list","version":1,"textFormat":1,"listType":"number","start":1,"tag":"ol"},{"children":[],"direction":null,"format":"","indent":0,"type":"paragraph","version":1,"textFormat":0,"textStyle":""},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"A few notes on each:","type":"text","version":1}],"direction":null,"format":"","indent":0,"type":"paragraph","version":1,"textFormat":0,"textStyle":""},{"children":[{"children":[{"detail":0,"format":1,"mode":"normal","style":"","text":"Bluetooth Low Energy","type":"text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":" is the natural choice when the user''s phone is the gateway, and it is ideal for first-time setup of almost any device.","type":"text","version":1}],"direction":null,"format":"","indent":0,"type":"listitem","version":1,"value":1},{"children":[{"detail":0,"format":1,"mode":"normal","style":"","text":"Wi-Fi","type":"text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":" carries lots of data, but it needs steady power and a router nearby. It''s rarely the right choice for a small battery device.","type":"text","version":1}],"direction":null,"format":"","indent":0,"type":"listitem","version":1,"value":2},{"children":[{"detail":0,"format":1,"mode":"normal","style":"","text":"LoRa","type":"text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":" trades speed for range and battery life: small packets, kilometres apart, for years.","type":"text","version":1}],"direction":null,"format":"","indent":0,"type":"listitem","version":1,"value":3},{"children":[{"detail":0,"format":1,"mode":"normal","style":"","text":"Wi-SUN","type":"text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":" builds a mesh where devices pass data to each other across a whole city. If one node goes down, the network reroutes itself. That''s why it''s used for smart metering and street lighting.","type":"text","version":1}],"direction":null,"format":"","indent":0,"type":"listitem","version":1,"value":4},{"children":[{"detail":0,"format":1,"mode":"normal","style":"","text":"Cellular IoT (NB-IoT, LTE-M, 4G)","type":"text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":" works almost anywhere there is mobile coverage, at the cost of a SIM and a data plan per device.","type":"text","version":1}],"direction":null,"format":"","indent":0,"type":"listitem","version":1,"value":5},{"children":[{"detail":0,"format":1,"mode":"normal","style":"","text":"RS485 with Modbus","type":"text","version":1},{"detail":0,"format":0,"mode":"normal","style":"","text":" is wired, simple and rock-solid in electrically noisy industrial IoT settings. No wireless at all, and that is often its biggest strength.","type":"text","version":1}],"direction":null,"format":"","indent":0,"type":"listitem","version":1,"value":6}],"direction":null,"format":"","indent":0,"type":"list","version":1,"textFormat":1,"listType":"bullet","start":1,"tag":"ul"},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Sometimes the answer is two","type":"text","version":1}],"direction":null,"format":"","indent":0,"type":"heading","version":1,"tag":"h2"},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Many real products combine protocols. On an energy meter retrofit project, we built one board that speaks wired RS485/Modbus to the meter and wireless Bluetooth Mesh to the network. The meter never had to change, and the data still reached the cloud.","type":"text","version":1}],"direction":null,"format":"","indent":0,"type":"paragraph","version":1,"textFormat":0,"textStyle":""},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Other common pairs: BLE for setup plus Wi-Fi for daily data, or LoRa in the field plus cellular at the gateway.","type":"text","version":1}],"direction":null,"format":"","indent":0,"type":"paragraph","version":1,"textFormat":0,"textStyle":""},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Decide at the design stage","type":"text","version":1}],"direction":null,"format":"","indent":0,"type":"heading","version":1,"tag":"h2"},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"The protocol shapes the antenna, the power supply, the enclosure (metal blocks radio), the firmware and the app. That''s why the right choice gets made at the design stage of IoT product development, not after the first field complaint.","type":"text","version":1}],"direction":null,"format":"","indent":0,"type":"paragraph","version":1,"textFormat":0,"textStyle":""},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Building an IoT product?","type":"text","version":1}],"direction":null,"format":"","indent":0,"type":"heading","version":1,"tag":"h2"},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Canopy Embedded Labs designs IoT hardware, firmware, apps and cloud dashboards as one team, in India and for clients worldwide. ","type":"text","version":1},{"children":[{"detail":0,"format":0,"mode":"normal","style":"","text":"Talk to an engineer","type":"text","version":1}],"direction":null,"format":"","indent":0,"type":"link","version":3,"fields":{"linkType":"custom","newTab":true,"url":"https://www.canopyembedded.com"},"id":"6adf48a20fa9ef7c2695258a"},{"detail":0,"format":0,"mode":"normal","style":"","text":" about the right connectivity for your product.","type":"text","version":1}],"direction":null,"format":"","indent":0,"type":"paragraph","version":1,"textFormat":0,"textStyle":""},{"children":[],"direction":null,"format":"","indent":0,"type":"paragraph","version":1,"textFormat":0,"textStyle":""}],"direction":null,"format":"","indent":0,"type":"root","version":1}}', NULL, NULL, 'How to Choose the Right IoT Protocol: BLE, Wi-Fi, LoRa, Wi-SUN, NB-IoT or RS485', 'Five questions that decide your IoT connectivity: range, data, power, environment and running cost. A plain-language guide from Canopy Embedded Labs.', NULL, 1, 1, 'auto', '2026-10-26T20:13:57.247Z', '2026-10-26T20:11:54.784Z', 'draft', '2026-10-26T20:13:57.388Z', '2026-10-26T20:13:57.388Z', 1, NULL, 0, NULL, NULL, NULL, NULL, NULL, 1, NULL);
